<template><ion-page><ion-header><ion-toolbar><ion-title class="toolbar-brand-right">Task<span>Edu</span></ion-title></ion-toolbar></ion-header><ion-content><main class="page-container"><header class="page-heading"><div><p>Dashboard acadêmico</p><h1>{{saudacao()}}, {{primeiroNome}} 👋</h1><span v-if="usuario?.turma" class="profile-chip">{{usuario?.turma}}</span></div><div class="notice-pill" v-if="alertas">🔔 {{alertas}} prazo(s) urgente(s)</div></header><section class="metric-grid"><article><span>Pendentes</span><strong>{{pendentes}}</strong><small>para organizar</small></article><article><span>Esta semana</span><strong>{{semana}}</strong><small>próximos 7 dias</small></article><article><span>Próximas provas</span><strong>{{provas}}</strong><small>prepare-se</small></article><article><span>Vencem hoje</span><strong>{{hojeTotal}}</strong><small>prioridade do dia</small></article></section><section class="progress-panel"><div><p class="section-kicker">SEU PROGRESSO</p><h2>{{concluidas}} de {{atividades.length}} atividades concluídas</h2></div><strong>{{percentual}}%</strong><ion-progress-bar :value="percentual/100"/></section></main></ion-content><BottomNav tipo="aluno"/></ion-page></template>
<script setup lang="ts">import { computed,ref } from 'vue';import { onIonViewWillEnter,IonContent,IonHeader,IonPage,IonProgressBar,IonTitle,IonToolbar } from '@ionic/vue';import BottomNav from '../components/BottomNav.vue';import { getUsuarioAtual } from '../services/auth.service';import { listarAtividadesPorTurma,listarProgressos } from '../services/atividades.service';import type { Atividade,ProgressoAtividade } from '../types';import { diferencaDias,estaSemana,saudacao } from '../utils/datas';const usuario=getUsuarioAtual(),atividades=ref<Atividade[]>([]),progressos=ref<ProgressoAtividade[]>([]);const primeiroNome=computed(()=>usuario.value?.nome.split(' ')[0]||'Aluno');const estado=(id:string)=>progressos.value.find(p=>p.atividadeId===id)||{concluida:false,favorita:false};const concluidas=computed(()=>atividades.value.filter(a=>estado(a.id).concluida).length);const pendentes=computed(()=>atividades.value.length-concluidas.value);const percentual=computed(()=>atividades.value.length?Math.round(concluidas.value/atividades.value.length*100):0);const semana=computed(()=>atividades.value.filter(a=>estaSemana(a.dataEntrega.toDate())&&!estado(a.id).concluida).length);const provas=computed(()=>atividades.value.filter(a=>a.tipo==='Prova'&&diferencaDias(a.dataEntrega.toDate())>=0).length);const hojeTotal=computed(()=>atividades.value.filter(a=>diferencaDias(a.dataEntrega.toDate())===0&&!estado(a.id).concluida).length);const alertas=computed(()=>atividades.value.filter(a=>{const d=diferencaDias(a.dataEntrega.toDate());return d>=0&&d<=1&&!estado(a.id).concluida}).length);onIonViewWillEnter(async()=>{if(usuario.value?.turma){[atividades.value,progressos.value]=await Promise.all([listarAtividadesPorTurma(usuario.value.turma),listarProgressos(usuario.value.uid)])}});</script>
